def dijkstra(graph, start, end):
    from heapq import heappush, heappop

    inf = float("inf")
    shortest_path = [inf] * len(graph)
    shortest_path[start] = 0
    unvisited = [(0, start)]

    while unvisited:
        dist, u = heappop(unvisited)

        if u == end:
            return shortest_path

        for v, w in graph[u]:
            new_dist = dist + w
            if new_dist < shortest_path[v]:
                shortest_path[v] = new_dist
                heappush(unvisited, (new_dist, v))

